-- Vendor bill invoice numbers are generated by the system and unique across all locations.
CREATE SEQUENCE IF NOT EXISTS vendor_bill_invoice_seq START WITH 1 INCREMENT BY 1;

-- Keep the first bill for each previously typed number; renumber the duplicates.
UPDATE vendor_bill v
SET invoice_number = 'VB-INV-' || LPAD(nextval('vendor_bill_invoice_seq')::text, 6, '0')
FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY invoice_number ORDER BY id) AS rn
    FROM vendor_bill
) d
WHERE v.id = d.id AND d.rn > 1;

CREATE UNIQUE INDEX IF NOT EXISTS uq_vendor_bill_invoice_number ON vendor_bill (invoice_number);
